def decide(recipient_reputation, round_num, my_history):
    # Use own cooperation history to determine a dynamic threshold
    # my_history is a list of booleans (True = cooperate, False = defect)
    if my_history is None or len(my_history) == 0:
        own_coop_count = 0
        own_total = 0
    else:
        own_coop_count = sum(1 for act in my_history if act)
        own_total = len(my_history)

    # Early rounds: defect to avoid being exploited
    if round_num < 3:
        return False

    # Dynamic threshold based on round number:
    # early-mid rounds are more cautious (require higher reputation)
    # later rounds become more lenient
    base_threshold = 0.7 if round_num < 10 else 0.4

    # If the agent has no history, rely purely on recipient reputation
    if own_total == 0:
        return recipient_reputation > 0.6

    # Use reputation and own cooperation fraction
    coop_fraction = own_coop_count / own_total

    # Cooperate only if recipient reputation is above threshold and
    # the agent has been cooperative in at least 40% of past interactions
    if recipient_reputation > base_threshold and coop_fraction > 0.4:
        return True
    else:
        return False

